  "repository": {
    "type": "git",
    "url": "git+https://github.com/aspose-email-foss/Aspose.JMAP-FOSS-for-TypeScript.git"
  },
  "bugs": {
    "url": "https://github.com/aspose-email-foss/Aspose.JMAP-FOSS-for-TypeScript/issues"
  },
  "keywords": ["jmap", "rfc8620", "rfc8621", "email", "mail", "client"],
